mapper.select:
SELECT B.FINPROD_ID finprodId,/**金融产品代码**/ B.FINPROD_TYPE finprodType,/**拆借方向**/ B.FINPROD_TYPE finprodTypeCode,/**拆借方向Code**/ B.PRIN prin,/**名义本金**/ B.CCY ccy,/**本金币种**/ B.CCY ccyCode,/**本金币种**/ to_char(B.VDATE,'yyyy-mm-dd') as vdate,/**起息日**/ to_char(B.MDATE,'yyyy-mm-dd') as mdate,/**到期日**/ B.TERM term,/**期限(天)**/ B.TERM_TYPE termType,/**期限品种**/ B.TERM_TYPE termTypeCode,/**期限品种**/ B.INT_TYPE intType,/**利率类型**/ B.INT_RATE*100 intRate,/**固定利率**/ B.INT_RATE_ID intRateId,/**利率编号**/ B.BASIS basis,/**计息基础**/ B.M_PRIN_AMT mPrinAmt,/**到期本金**/ B.M_INT_AMT mIntAmt,/**到期利息**/ B.M_TRADE_AMT mTradeAmt,/**到期金额**/ C.TYPE_2 type2,/**分类2**/ C.TYPE_2 type2Code,/**分类2Code**/ B.CAPI_INCOME_FEATURE capiIncomeFeature,/**本金收益特征**/ B.CAPI_INCOME_FEATURE capiIncomeFeatureCode,/**本金收益特征**/ B.CALENDAR_ID calendarId,/**交易日历**/ D.CALENDAR_NAME calendarName/**交易日历名称**/ FROM FIN_TRADE_PRODUCT B LEFT JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO D ON D.CALENDAR_ID = B.CALENDAR_ID WHERE (B.BRANCH = 0 OR B.BRANCH IS NULL) AND B.FINPROD_ID =#{finprodId} AND B.FINPROD_TYPE =#{finprodType}
union all
SELECT B.FINPROD_ID finprodId,/**金融产品代码**/ B.FINPROD_TYPE finprodType,/**拆借方向**/ B.FINPROD_TYPE finprodTypeCode,/**拆借方向Code**/ null prin,/**名义本金**/ B.CCY ccy,/**本金币种**/ B.CCY ccyCode,/**本金币种**/ to_char(B.VDATE,'yyyy-mm-dd') as vdate,/**起息日**/ to_char(B.MDATE,'yyyy-mm-dd') as mdate,/**到期日**/ B.Mdate - B.Vdate term,/**期限(天)**/ null termType,/**期限品种**/ null termTypeCode,/**期限品种**/ null intType,/**利率类型**/ null intRate,/**固定利率**/ null intRateId,/**利率编号**/ vccr.basis basis, /**计息基础**/ null mPrinAmt,/**到期本金**/ null mIntAmt,/**到期利息**/ null mTradeAmt,/**到期金额**/ C.TYPE_2 type2,/**分类2**/ C.TYPE_2 type2Code,/**分类2Code**/ B.CAPI_INCOME_FEATURE capiIncomeFeature,/**本金收益特征**/ B.CAPI_INCOME_FEATURE capiIncomeFeatureCode,/**本金收益特征**/ B.CALENDAR_ID calendarId,/**交易日历**/ D.CALENDAR_NAME calendarName/**交易日历名称**/ FROM fin_product B LEFT JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.FINPROD_ID LEFT JOIN MST_CALENDAR_INFO D ON D.CALENDAR_ID = B.CALENDAR_ID
left join (select vccr.* from fin_CASH_CALC_RULE vccr where vccr.eff_date = (select max(cash_rule.eff_date) from fin_CASH_CALC_RULE cash_rule where cash_rule.finprod_id = vccr.finprod_id and cash_rule.finprod_type = vccr.finprod_type)) vccr on B.finprod_id = vccr.finprod_id and B.finprod_type = vccr.finprod_type
WHERE B.FINPROD_ID = #{finprodId} AND B.FINPROD_TYPE = #{finprodType}
